export const ADMIN_PAGE = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex,nofollow\">\n<title>Stumpire admin | Run The Arcade</title>\n<style>\n  body{margin:0;background:#0f1420;color:#eef2f8;font:15px/1.45 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}\n  main{max-width:980px;margin:0 auto;padding:16px}\n  section{background:#18202f;border:1px solid #2a3448;border-radius:12px;padding:14px;margin-bottom:14px}\n  h1{font-size:22px} h2{font-size:17px;margin:0 0 8px}\n  input,select,textarea,button{font:inherit;color:#eef2f8;background:#0c111b;border:1px solid #2a3448;border-radius:8px;padding:7px 9px}\n  button{background:#24304a;cursor:pointer} button.go{background:#2f6fed;border-color:#2f6fed}\n  textarea{width:100%;min-height:190px;font-family:ui-monospace,Menlo,monospace;font-size:13px}\n  table{border-collapse:collapse;width:100%;font-size:13px} td,th{border-bottom:1px solid #2a3448;padding:4px 6px;text-align:left}\n  .err{color:#ff6b6b} .warn{color:#ffc94d} .okc{color:#3ecf8e} .mut{color:#9aa7bd}\n  .row{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:6px 0}\n</style>\n</head>\n<body>\n<main>\n  <h1>Stumpire admin</h1>\n  <p class=\"mut\">Testers only. Every change here is live the moment it is saved.</p>\n\n  <section>\n    <h2>Access</h2>\n    <div class=\"row\">Mode <select id=\"mode\"><option>off</option><option>testers</option><option>public</option></select> <button id=\"saveMode\">Save mode</button> <span class=\"mut\">off: admins only. testers: the list below. public: everybody.</span></div>\n    <div class=\"row\"><input id=\"tName\" placeholder=\"username\"> <select id=\"tRole\"><option>tester</option><option>admin</option></select> <button class=\"go\" id=\"addT\">Add tester</button></div>\n    <table id=\"testers\"></table>\n  </section>\n\n  <section>\n    <h2>Author a prompt</h2>\n    <div class=\"row\">At-bat <select id=\"atBat\"><option value=\"0\">1</option><option value=\"1\">2</option><option value=\"2\">3</option><option value=\"3\">4</option><option value=\"4\">5</option></select>\n      <button id=\"preview\">Preview</button> <button class=\"go\" id=\"savePrompt\">Save prompt</button> <select id=\"load\"><option value=\"\">Load a saved prompt</option></select></div>\n    <textarea id=\"def\">{\n  \"id\": \"nba-pg-all-star\",\n  \"text\": \"A point guard who made an All-Star team\",\n  \"league\": \"NBA\",\n  \"type\": \"athlete\",\n  \"years\": [1960, 2025],\n  \"where\": [ { \"k\": \"award\", \"v\": \"NBA All-Star\" }, { \"k\": \"pos\", \"v\": \"Point Guard\" } ],\n  \"wildcard\": \"nba-steve-nash-1990\",\n  \"arguable\": []\n}</textarea>\n    <div id=\"pv\"></div>\n  </section>\n\n  <section>\n    <h2>Publish a slate</h2>\n    <div class=\"row\">Date <input id=\"pDate\" type=\"date\"></div>\n    <div class=\"row\" id=\"pPick\"></div>\n    <button class=\"go\" id=\"publish\">Publish and freeze</button>\n    <div id=\"pOut\"></div>\n  </section>\n\n  <section><h2>Challenges</h2><div id=\"ch\"></div></section>\n  <section><h2>Benefit of the doubt review</h2><div id=\"rv\"></div></section>\n  <section><h2>NO PITCH log</h2><p class=\"mut\">What players typed that matched nobody. Grow the alias table from this.</p><div id=\"np\"></div></section>\n</main>\n<script src=\"https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.45.4/dist/umd/supabase.js\"></script>\n<script src=\"/arcade/auth.js?v=4\"></script>\n<script>\n(function () {\n  'use strict';\n  var A = window.RTG_AUTH;\n  function $(id) { return document.getElementById(id); }\n  function esc(s) { return String(s == null ? '' : s).replace(/[&<>\"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]; }); }\n  function api(method, path, body) {\n    var h = { 'Content-Type': 'application/json' };\n    var t = A && A.token && A.token(); if (t) h.Authorization = 'Bearer ' + t;\n    return fetch('/api/stumpire/' + path, { method: method, headers: h, body: body ? JSON.stringify(body) : undefined })\n      .then(function (r) { return r.json().catch(function () { return {}; }).then(function (j) { j._status = r.status; return j; }); });\n  }\n  var PROMPTS = [];\n\n  function loadTesters() {\n    api('GET', 'admin/testers').then(function (r) {\n      $('mode').value = r.mode;\n      $('testers').innerHTML = '<tr><th>User</th><th>Role</th><th></th></tr>' + (r.testers || []).map(function (t) {\n        return '<tr><td>' + esc(t.username || t.user_id) + '</td><td>' + esc(t.role) + '</td><td><button data-rm=\"' + esc(t.user_id) + '\">Remove</button></td></tr>';\n      }).join('');\n    });\n  }\n  $('saveMode').onclick = function () { api('POST', 'admin/mode', { mode: $('mode').value }).then(loadTesters); };\n  $('addT').onclick = function () { api('POST', 'admin/testers', { username: $('tName').value.trim(), role: $('tRole').value }).then(function (r) { if (r._status !== 200) alert(r.error); $('tName').value = ''; loadTesters(); }); };\n  $('testers').onclick = function (e) { var b = e.target.closest('[data-rm]'); if (b && confirm('Remove this tester?')) api('DELETE', 'admin/testers', { userId: b.dataset.rm }).then(function (r) { if (r._status !== 200) alert(r.error); loadTesters(); }); };\n\n  function def() { try { return JSON.parse($('def').value); } catch (e) { alert('That is not valid JSON: ' + e.message); return null; } }\n  $('preview').onclick = function () {\n    var d = def(); if (!d) return;\n    api('POST', 'admin/preview', { prompt: d, atBat: Number($('atBat').value) }).then(function (r) {\n      if (r._status !== 200) { $('pv').innerHTML = '<p class=\"err\">' + esc(r.error) + '</p>'; return; }\n      var h = '<p><b>' + r.count + '</b> valid answers. Bands: single ' + r.bands[1] + ', double ' + r.bands[2] + ', triple ' + r.bands[3] + ', home run ' + r.bands[4] + '.</p>';\n      if (r.called) h += '<p>Called (' + Math.round(r.called.coverage * 100) + '% of expected share): ' + esc(r.called.names.join(', ')) + '</p>';\n      h += r.errors.map(function (e) { return '<p class=\"err\">Blocks publishing: ' + esc(e) + '</p>'; }).join('');\n      h += r.warnings.map(function (e) { return '<p class=\"warn\">Check: ' + esc(e) + '</p>'; }).join('');\n      if (!r.errors.length) h += '<p class=\"okc\">Passes every rule for this at-bat.</p>';\n      h += '<table><tr><th>#</th><th>Answer</th><th>Expected share</th><th>Depth</th><th>Hit</th><th></th></tr>' + r.sample.map(function (x, i) {\n        return '<tr><td>' + (i + 1) + '</td><td>' + esc(x.name) + ' <span class=\"mut\">' + esc(x.id) + '</span></td><td>' + (x.expected * 100).toFixed(2) + '%</td><td>' + (x.depth * 100).toFixed(1) + '%</td><td>' + ['', '1B', '2B', '3B', 'HR'][x.tier] + '</td><td>' + (x.called ? 'called' : '') + (x.arguable ? ' arguable' : '') + '</td></tr>';\n      }).join('') + '</table>';\n      $('pv').innerHTML = h;\n    });\n  };\n  $('savePrompt').onclick = function () { var d = def(); if (d) api('POST', 'admin/prompts', { prompt: d }).then(function (r) { alert(r._status === 200 ? 'Saved ' + r.saved : r.error); loadPrompts(); }); };\n  $('load').onchange = function () { var p = PROMPTS.find(function (x) { return x.id === $('load').value; }); if (p) { var c = Object.assign({}, p); delete c.status; $('def').value = JSON.stringify(c, null, 2); } };\n\n  function loadPrompts() {\n    api('GET', 'admin/prompts').then(function (r) {\n      PROMPTS = r.prompts || [];\n      var opts = PROMPTS.map(function (p) { return '<option value=\"' + esc(p.id) + '\">' + esc(p.league + ' · ' + p.text + ' (' + p.status + ')') + '</option>'; }).join('');\n      $('load').innerHTML = '<option value=\"\">Load a saved prompt</option>' + opts;\n      var picks = ''; for (var i = 0; i < 5; i++) picks += '<label>At-bat ' + (i + 1) + ' <select class=\"pp\"><option value=\"\"></option>' + opts + '</select></label>';\n      $('pPick').innerHTML = picks;\n    });\n  }\n  $('publish').onclick = function () {\n    var ids = Array.prototype.map.call(document.querySelectorAll('.pp'), function (s) { return s.value; });\n    if (!confirm('Publishing freezes every grade on this slate. Go?')) return;\n    api('POST', 'admin/publish', { date: $('pDate').value, promptIds: ids }).then(function (r) {\n      $('pOut').innerHTML = r.published ? '<p class=\"okc\">Published slate #' + r.no + ' for ' + esc(r.date) + ' (' + r.rows + ' answers frozen).</p>'\n        : (r.errors || [r.error]).map(function (e) { return '<p class=\"err\">' + esc(e) + '</p>'; }).join('');\n      loadPrompts();\n    });\n  };\n\n  function loadQueues() {\n    api('GET', 'admin/challenges').then(function (r) {\n      var c = r.challenges || [];\n      $('ch').innerHTML = c.length ? '<table><tr><th>Slate</th><th>At-bat</th><th>Typed</th><th>Entity</th><th>Ruling</th><th>Note</th><th></th></tr>' + c.map(function (x) {\n        return '<tr><td>' + esc(x.slate_date) + '</td><td>' + (x.at_bat + 1) + '</td><td>' + esc(x.raw) + '</td><td>' + esc(x.entity_id) + '</td><td>' + esc(x.ruling) + '</td><td>' + esc(x.note) + '</td>' +\n          '<td><button data-up=\"' + x.id + '\">Uphold</button> <button data-dn=\"' + x.id + '\">Deny</button></td></tr>';\n      }).join('') + '</table>' : '<p class=\"mut\">No open challenges.</p>';\n    });\n    api('GET', 'admin/review').then(function (r) {\n      var v = r.review || [];\n      $('rv').innerHTML = v.length ? '<table>' + v.map(function (x) { return '<tr><td>' + esc(x.slate_date) + '</td><td>' + esc(x.prompt_id) + '</td><td>' + esc(x.entity_id) + '</td><td>' + esc(x.reason) + '</td></tr>'; }).join('') + '</table>' : '<p class=\"mut\">Nothing to review.</p>';\n    });\n    api('GET', 'admin/nopitch').then(function (r) {\n      var v = r.nopitch || [];\n      $('np').innerHTML = v.length ? '<table>' + v.map(function (x) { return '<tr><td>' + esc(x.prompt_id) + '</td><td>' + esc(x.raw) + '</td></tr>'; }).join('') + '</table>' : '<p class=\"mut\">Nothing logged.</p>';\n    });\n  }\n  $('ch').onclick = function (e) {\n    var up = e.target.closest('[data-up]'), dn = e.target.closest('[data-dn]');\n    if (!up && !dn) return;\n    var id = Number((up || dn).dataset.up || (up || dn).dataset.dn);\n    var body = { id: id, upheld: !!up, resolution: prompt(up ? 'What was fixed? (alias added, award added...)' : 'Why denied?') || '' };\n    if (up) { var ent = prompt('Entity id the player meant (blank to keep the logged one)'); if (ent) body.entityId = ent.trim(); }\n    api('POST', 'admin/challenges/resolve', body).then(function (r) { if (r._status !== 200) alert(r.error); loadQueues(); });\n  };\n\n  function boot() { loadTesters(); loadPrompts(); loadQueues(); }\n  $('pDate').value = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/New_York' }).format(new Date(Date.now() + 86400000));\n  if (A && A.boot && A.boot()) { var go = false; A.onChange(function (s) { if (s.resolved && !go) { go = true; boot(); } }); setTimeout(function () { if (!go) { go = true; boot(); } }, 2500); }\n  else boot();\n})();\n</script>\n</body>\n</html>\n";
